CREATE TABLE "PersonalUser" ("id" TEXT PRIMARY KEY,"singleton" INTEGER NOT NULL DEFAULT 1 CHECK ("singleton" = 1),"username" TEXT NOT NULL,"passwordHash" TEXT NOT NULL);
CREATE UNIQUE INDEX "PersonalUser_singleton_key" ON "PersonalUser"("singleton");
CREATE UNIQUE INDEX "PersonalUser_username_key" ON "PersonalUser"("username");
CREATE TABLE "Workspace" ("id" TEXT PRIMARY KEY,"ownerId" TEXT NOT NULL REFERENCES "PersonalUser"("id") ON DELETE CASCADE ON UPDATE CASCADE,"name" TEXT NOT NULL DEFAULT '我的工作台',"preferences" JSONB NOT NULL DEFAULT '{}',"preferenceVersion" INTEGER NOT NULL DEFAULT 1,"demoInitialized" BOOLEAN NOT NULL DEFAULT false);
CREATE UNIQUE INDEX "Workspace_ownerId_key" ON "Workspace"("ownerId");
CREATE TABLE "LoginSession" ("digest" TEXT PRIMARY KEY,"ownerId" TEXT NOT NULL REFERENCES "PersonalUser"("id") ON DELETE CASCADE ON UPDATE CASCADE,"expiresAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "LoginSession_ownerId_idx" ON "LoginSession"("ownerId");
CREATE TABLE "StudioRecord" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE,"kind" TEXT NOT NULL,"data" JSONB NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"sample" BOOLEAN NOT NULL DEFAULT false,"deletedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "StudioRecord_workspaceId_kind_deletedAt_updatedAt_idx" ON "StudioRecord"("workspaceId","kind","deletedAt","updatedAt");
CREATE TABLE "RecordVersion" ("id" TEXT PRIMARY KEY,"recordId" TEXT NOT NULL REFERENCES "StudioRecord"("id") ON DELETE CASCADE ON UPDATE CASCADE,"version" INTEGER NOT NULL,"data" JSONB NOT NULL,"deleted" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "RecordVersion_recordId_version_key" ON "RecordVersion"("recordId","version");
CREATE TABLE "StudioFile" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE,"recordId" TEXT NOT NULL REFERENCES "StudioRecord"("id") ON DELETE CASCADE ON UPDATE CASCADE,"name" TEXT NOT NULL,"mediaType" TEXT NOT NULL,"size" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "StudioFile_workspaceId_recordId_idx" ON "StudioFile"("workspaceId","recordId");
